scope = {Pgen.assumption_class; Pef.assumption_class; Phv.assumption_class; ...
    Pq0.assumption_class; Pbl.assumption_class; 'PRIMARY'; 'PRIMARY'; 'PRIMARY'};
setRows = table(dids, sets, units, basis, src, val, cts, tms, cvs, prov, scope, ...
