function P = phase5b_pickup(device, Iload_A, Imin_fault_A)
%PHASE5B_PICKUP  Pickup-setting engine v2: Siemens DT baseline + study rules (Phase-5b Tasks C3/C4).
%   P = PHASE5B_PICKUP(device, Iload_A, Imin_fault_A) returns struct P with
%   v1 fields (setting/unit/basis/source/validation/device_id/
%   assumption_class) plus study tags (tms/curve/use_phase5_time/
%   setting_sec_A; EF rows also carry ef_tms) for STUDY devices, or tdef/
%   time_status/curve/use_phase5_time/setting_sec_A for the PHYSICAL
%   baseline device GEN-51-SIEMENS-BL.
%
%   Inputs mirror phase5_pickup (frozen v1, never modified):
%     device       registry row scalar struct (must carry non-empty char
%                  device_id; baseline branch dispatches on
%                  'GEN-51-SIEMENS-BL').
%     Iload_A      normal-load anchor in PRIMARY A (scalar, finite, >= 0).
%     Imin_fault_A minimum fault current in PRIMARY A (scalar, finite, > 0).
%
%   Baseline branch (spec S3/S5; ledger SIEMENS-Igt-1.14A +
%   SIEMENS-tdef-3s-??, class USER_ASSERTED_PENDING_DOC):
%     7UM622 50/51 I> ON, inverse disabled, I> = 1.14 A secondary
%     ~= 17171 A primary via generator T1/T2 15000/1 CTs (SOURCE-BACKED,
%     unchanged), tdef = 3.00 s marked ??/coordination-pending so operating
%     time stays NOT-DETERMINABLE-??-PENDING-COORDINATION until coordination
%     info arrives. DERIVED cross-check recorded (not substituted):
%     1.20 x Imax 14309 A = 17170.8 A ~= 17171 A; 17171/15000 = 1.1447 A
%     ~= 1.14 A secondary. Inverse (phase5_time/phase5_curve) is prohibited
%     on this row by contract: P.curve = 'DT-??' (refused by the locked v1
%     library: only exact 'DT' enters the definite-time path) and
%     P.use_phase5_time = false (downstream callers must check the flag and
%     never dispatch this row to phase5_time).
%
%   Served ids: PHYSICAL 'GEN-51-SIEMENS-BL' (DT baseline, inverse
%   prohibited) and STUDY 'GEN-51'/'GEN-51-SI', 'GSUT-HV-51', 'GIS-Q0-51',
%   'GEN-51N'/'GEN-51N-SI-STUDY' (SI, TMS 0.20 phase / 0.15 EF, inverse
%   allowed). 'GIS-Q0-50' stays DISABLED (errors; registry TMS never
%   enables it); 'LINE-21-note'/'REMOTE-GRID-boundary' have no settings
%   (errors). Any other id errors phase5b_pickup:unimplemented — no stub
%   behavior by design (global constraint: never invent settings; honest
%   error instead of tuned-to-pass numbers).
%
%   All errors are 'phase5b'-prefixed (reuse of v1 functions keeps 'phase5').
if nargin ~= 3
    error('phase5b_pickup:args', 'usage: P = phase5b_pickup(device, Iload_A, Imin_fault_A).');
end
if ~isstruct(device) || ~isscalar(device) || ~isfield(device, 'device_id')
    error('phase5b_pickup:device', 'device must be a scalar struct with device_id (registry row).');
end
idraw = device.device_id;
if isstring(idraw) && isscalar(idraw)
    idraw = char(idraw);
end
if ~ischar(idraw) || isempty(strtrim(idraw))
    error('phase5b_pickup:device', 'device.device_id must be non-empty char (registry row).');
end
id = strtrim(idraw);
if ~isnumeric(Iload_A) || ~isscalar(Iload_A) || ~isreal(Iload_A) ...
        || ~isfinite(Iload_A) || Iload_A < 0
    error('phase5b_pickup:load', 'Iload_A must be a real finite scalar >= 0 (PRIMARY A anchor).');
end
if ~isnumeric(Imin_fault_A) || ~isscalar(Imin_fault_A) || ~isreal(Imin_fault_A) ...
        || ~isfinite(Imin_fault_A) || Imin_fault_A <= 0
    error('phase5b_pickup:fault', 'Imin_fault_A must be a real finite scalar > 0 (PRIMARY A).');
end
Iload_A = double(Iload_A);
Imin_fault_A = double(Imin_fault_A);
isBaseline = strcmp(id, 'GEN-51-SIEMENS-BL');
isGenStudy = strcmp(id, 'GEN-51') || strcmp(id, 'GEN-51-SI');
isGsut = strcmp(id, 'GSUT-HV-51');
isGis = strcmp(id, 'GIS-Q0-51');
isEfStudy = strcmp(id, 'GEN-51N') || strcmp(id, 'GEN-51N-SI-STUDY');
if strcmp(id, 'GIS-Q0-50')
    error('phase5b_pickup:disabled', ['phase5b_pickup: GIS-Q0-50 high-set DISABLED-unless-justified ' ...
        '(NOT DETERMINABLE FROM AVAILABLE DATA; no high-set invented; ' ...
        'registry TMS-0.20 never enables it).']);
end
if strcmp(id, 'LINE-21-note') || strcmp(id, 'REMOTE-GRID-boundary')
    error('phase5b_pickup:unsupported', ['phase5b_pickup: %s has no settings ' ...
        '(NOT DETERMINABLE FROM AVAILABLE DATA; NOTE/boundary only).'], id);
end
if ~isBaseline && ~isGenStudy && ~isGsut && ~isGis && ~isEfStudy
    error('phase5b_pickup:unimplemented', ['phase5b_pickup: %s is not a served device ' ...
        '(served: GEN-51-SIEMENS-BL, GEN-51/GEN-51-SI, GSUT-HV-51, GIS-Q0-51, ' ...
        'GEN-51N/GEN-51N-SI-STUDY; GIS-Q0-50 DISABLED; notes/boundary unsupported). ' ...
        'No stub behavior by design (never invent settings).'], id);
end
if ~isBaseline
    % === C4 study rule branch (spec S6; master §21 Status C; ledger OC-1.2xload/TMS-0.20/EF-TMS-0.15) ===
    TMS_PHASE = 0.20;  % ledger TMS-0.20, ENGINEERING_ASSUMPTION, Status-C initial
    TMS_EF = 0.15;     % ledger EF-TMS-0.15, ENGINEERING_ASSUMPTION, master §21
    if isEfStudy
        % GEN-51N-SI-STUDY: 5 A primary retained sensitive case, scope SENSITIVITY.
        CTR = 15000;   % generator T1/T2 CT (ledger GEN-T1T2-15000, SOURCE-BACKED)
        if isfield(device, 'ct_ratio') && isnumeric(device.ct_ratio) ...
                && isscalar(device.ct_ratio) && isreal(device.ct_ratio) ...
                && isfinite(device.ct_ratio) && device.ct_ratio ~= CTR
            error('phase5b_pickup:ct', 'phase5b_pickup: GEN-51N study needs generator 15000/1 CT (got %.0f).', device.ct_ratio);
        end
        IS = 5;  % A primary, fixed retained sensitive case (never retuned)
        IS_SEC = IS / CTR;  % 0.3333 mA secondary
        unit = 'A-primary';
        basis = 'must-detect-F1-LG-7.27A-primary:5A-retained-sensitive-case-scope-SENSITIVITY-EF-TMS-0.15-study';
        source = ['ENGINEERING_ASSUMPTION-study-setting-SENSITIVE:' ...
            '5A-primary-via-15000/1-0.33mA-secondary-scope-SENSITIVITY;' ...
            'ENGINEERING_ASSUMPTION-EF-TMS-0.15-ledger-EF-TMS-0.15-master-S21'];
        mFault = Imin_fault_A / IS;
        validation = sprintf(['detects-F1-LG-%.5fA-with-margin-%.3f;' ...
            'SENSITIVE-susceptible-to-noise-reported-as-limitation;' ...
            'EF-TMS-0.15-per-master-S21;T7-converts-via-CT-15000/1'], ...
            Imin_fault_A, mFault);
        P = struct('setting', IS, 'unit', unit, 'basis', basis, ...
            'source', source, 'validation', validation, ...
            'device_id', id, 'assumption_class', 'SENSITIVITY', ...
            'tms', TMS_EF, 'ef_tms', TMS_EF, 'curve', 'SI', ...
            'use_phase5_time', true, 'setting_sec_A', IS_SEC);
        return;
    end
    if isGenStudy
        % GEN-51-SI: 1.20 x Imax 14309 A = 17170.8 A primary, max-operating-
        % current basis (ledger GEN-Imax-14309, SOURCE-BACKED). Converges
        % with the Siemens DT baseline pickup 17171 A (rel-err ~1e-5);
        % characteristic differs: study SI with TMS 0.20 (inverse allowed)
        % vs PHYSICAL DT tdef 3.00 s ?? (inverse prohibited).
        CTR = 15000;   % generator T1/T2 CT (ledger GEN-T1T2-15000, SOURCE-BACKED)
        IMAX = 14309;  % A generator max operating current (ledger GEN-Imax-14309)
        if isfield(device, 'ct_ratio') && isnumeric(device.ct_ratio) ...
                && isscalar(device.ct_ratio) && isreal(device.ct_ratio) ...
                && isfinite(device.ct_ratio) && device.ct_ratio ~= CTR
            error('phase5b_pickup:ct', 'phase5b_pickup: GEN-51 study needs generator 15000/1 CT (got %.0f).', device.ct_ratio);
        end
        IS = 1.20 * IMAX;  % 17170.8 A primary
        IS_SEC = IS / CTR;  % 1.14472 A secondary
        unit = 'A-primary';
        basis = ['max-operating-current:1.20xImax-14309A=17170.8A-primary-' ...
            'SI-TMS-0.20-study;converges-with-Siemens-DT-baseline-17171A-' ...
            'characteristic-differs-SI-vs-DT'];
        source = ['DERIVED-study-setting:1.20xImax-GEN-Imax-14309A-SOURCE-BACKED;' ...
            'ENGINEERING_ASSUMPTION-OC-1.2xload-ledger-OC-1.2xload;' ...
            'ENGINEERING_ASSUMPTION-TMS-0.20-ledger-TMS-0.20;' ...
            'converges-with-USER_ASSERTED_PENDING_DOC-SIEMENS-Igt-1.14A-17171A-SI-vs-DT'];
        if Iload_A > 0
            mLoad = IS / Iload_A;
        else
            mLoad = Inf;
        end
        mFault = Imin_fault_A / IS;
        xerr = abs(IS - 17171) / 17171;
        validation = sprintf(['no-trip-on-load-vs-Iload-%.3fA(margin-%.3f);' ...
            'must-detect-vs-Imin-%.3fA(margin-%.3f);' ...
            'convergence-with-Siemens-DT-17171A(rel-err-%.6f)-characteristic-differs-SI-TMS-0.20-vs-DT;' ...
            'T7-converts-via-CT-15000/1'], ...
            Iload_A, mLoad, Imin_fault_A, mFault, xerr);
        P = struct('setting', IS, 'unit', unit, 'basis', basis, ...
            'source', source, 'validation', validation, ...
            'device_id', id, 'assumption_class', 'PRIMARY', ...
            'tms', TMS_PHASE, 'curve', 'SI', ...
            'use_phase5_time', true, 'setting_sec_A', IS_SEC);
        return;
    end
    if isGsut
        % GSUT-HV-51: 1.2 x max(rated 1150 A, Iload anchor 870.7726 A) =
        % 1380 A primary via 1600/1 (ledger GSUT-1600/1-cores, SOURCE-BACKED;
        % GSUT_HV FL anchor 0.870772573866956 kA from phase4_ct_data.csv).
        if ~isfield(device, 'rated_A') || ~isnumeric(device.rated_A) ...
                || ~isscalar(device.rated_A) || ~isreal(device.rated_A) ...
                || ~isfinite(device.rated_A) || device.rated_A <= 0
            error('phase5b_pickup:rated', 'phase5b_pickup: GSUT-HV-51 needs finite rated_A (registry 1150 A).');
        end
        CTR = 1600;    % GSUT-HV study CT (ledger GSUT-1600/1-cores, SOURCE-BACKED)
        if isfield(device, 'ct_ratio') && isnumeric(device.ct_ratio) ...
                && isscalar(device.ct_ratio) && isreal(device.ct_ratio) ...
                && isfinite(device.ct_ratio) && device.ct_ratio ~= CTR
            error('phase5b_pickup:ct', 'phase5b_pickup: GSUT-HV-51 needs study 1600/1 CT (got %.0f).', device.ct_ratio);
        end
        rated = double(device.rated_A);
        refA = max(rated, Iload_A);
        IS = 1.2 * refA;  % 1380 A at rated 1150 A anchor
        IS_SEC = IS / CTR;  % 0.8625 A secondary
        unit = 'A-primary';
        basis = sprintf(['above-full-load-below-min-fault:' ...
            '1.2xmax(rated-%.4fA,Iload-%.4fA)=%.4fA-primary-via-1600/1'], ...
            rated, Iload_A, IS);
        source = ['DERIVED-study-setting:1.2xmax-rated-1150A-Iload-anchor-870.7726A;' ...
            'SOURCE-BACKED-CT-1600/1-ledger-GSUT-1600/1-cores;' ...
            'ENGINEERING_ASSUMPTION-TMS-0.20-ledger-TMS-0.20'];
        if Iload_A > 0
            mLoad = IS / Iload_A;
        else
            mLoad = Inf;
        end
        mFault = Imin_fault_A / IS;
        validation = sprintf(['no-trip-on-load-vs-Iload-%.4fA(margin-%.3f);' ...
            'must-detect-vs-Imin-%.3fA(margin-%.3f);' ...
            'T7-converts-via-CT-1600/1'], ...
            Iload_A, mLoad, Imin_fault_A, mFault);
        P = struct('setting', IS, 'unit', unit, 'basis', basis, ...
            'source', source, 'validation', validation, ...
            'device_id', id, 'assumption_class', 'PRIMARY', ...
            'tms', TMS_PHASE, 'curve', 'SI', ...
            'use_phase5_time', true, 'setting_sec_A', IS_SEC);
        return;
    end
    % GIS-Q0-51: 1.2 x Iload FL anchor (LINE_Q9 0.869956651959241 kA from
    % phase4_ct_data.csv FL_anchor_kA) via 1600/1 (ledger GIS-bay-1600/1,
    % SOURCE-BACKED); 1.2 x 869.956651959241 = 1043.94798235109 A.
    if ~(Iload_A > 0)
        error('phase5b_pickup:load', 'phase5b_pickup: GIS-Q0-51 needs FL_anchor Iload_A > 0 (from phase4_ct_data.csv FL_anchor_kA x1000).');
    end
    CTR = 1600;        % GIS bay study CT (ledger GIS-bay-1600/1, SOURCE-BACKED)
    if isfield(device, 'ct_ratio') && isnumeric(device.ct_ratio) ...
            && isscalar(device.ct_ratio) && isreal(device.ct_ratio) ...
            && isfinite(device.ct_ratio) && device.ct_ratio ~= CTR
        error('phase5b_pickup:ct', 'phase5b_pickup: GIS-Q0-51 needs study 1600/1 CT (got %.0f).', device.ct_ratio);
    end
    IS = 1.2 * Iload_A;
    IS_SEC = IS / CTR;
    unit = 'A-primary';
    basis = 'above-full-load-below-min-fault:1.2xFL_anchor-LINE_Q9-0.869956651959241kA-from-phase4_ct_data.csv-via-1600/1';
    source = ['DERIVED-study-setting:1.2xFL_anchor-LINE_Q9-0.869956651959241kA;' ...
        'SOURCE-BACKED-CT-1600/1-ledger-GIS-bay-1600/1;' ...
        'ENGINEERING_ASSUMPTION-TMS-0.20-ledger-TMS-0.20'];
    mLoad = IS / Iload_A;
    mFault = Imin_fault_A / IS;
    validation = sprintf(['no-trip-on-load-vs-FL_anchor-%.6fA(margin-%.3f);' ...
        'must-detect-vs-Imin-%.3fA(margin-%.3f);' ...
        'T7-converts-via-CT-1600/1'], ...
        Iload_A, mLoad, Imin_fault_A, mFault);
    P = struct('setting', IS, 'unit', unit, 'basis', basis, ...
        'source', source, 'validation', validation, ...
        'device_id', id, 'assumption_class', 'PRIMARY', ...
        'tms', TMS_PHASE, 'curve', 'SI', ...
        'use_phase5_time', true, 'setting_sec_A', IS_SEC);
    return;
end
