function [np, nf] = test_phase5b_assumptions()
%TEST_PHASE5B_ASSUMPTIONS  Master-correction central-set coverage (11 checks, §29).
%   Covers: CT conflict, rated-vs-anchor, GSUT pickup, Q0 provisional,
%   GEN-51N neutral CT, PRIMARY/SENSITIVITY separation, runner, 87G/87T,
%   Q0 duty, provenance consistency, sanity arithmetic.
T = t_case('test_phase5b_assumptions');
R = phase5b_registry();
ids = {R.devices.device_id};
% 1. GSUT CT conflict classification
g = R.devices(strcmp(ids, 'GSUT-HV-51'));
T = T.chk(g.ct_ratio == 1600 && strcmp(g.ct_source, 'ENGINEERING_ASSUMPTION'), 'GSUT study CT 1600/1 ENGINEERING_ASSUMPTION');
T = T.chk(~isempty(strfind(g.provenance, 'NOT_DETERMINABLE')), 'GSUT installed CT NOT_DETERMINABLE in provenance');
% 2. GSUT rated vs anchor
T = T.chk(abs(g.rated_A - 1292.8) < 1, 'GSUT rated 1292.8 A nameplate');
anchor = 458e6 / (sqrt(3) * 230e3);
T = T.chk(abs(anchor - 1149.7) < 1.0, 'GSUT anchor 1149.7 A from 458MVA');
nameplate = 515e6 / (sqrt(3) * 230e3);
T = T.chk(abs(nameplate - 1292.8) < 1.0, 'GSUT nameplate 1292.8 A from 515MVA');
% 3. GSUT pickup calculation
Phv = phase5b_pickup(g, 870.7726, 43758.86);
T = T.chk(abs(Phv.setting - 1380) < 1e-9, 'GSUT pickup 1380 A');
T = T.chk(abs(Phv.setting_sec_A - 0.8625) < 1e-12, 'GSUT secondary 0.8625 A');
T = T.chk(abs(Phv.tms - 0.55) < 1e-12, 'GSUT TMS 0.55');
% 4. Q0 provisional pickup
q = R.devices(strcmp(ids, 'GIS-Q0-51'));
Pq0 = phase5b_pickup(q, 869.9567, 43758.86);
T = T.chk(abs(Pq0.setting - 1500) < 1e-9, 'Q0 pickup 1500 A provisional');
T = T.chk(abs(Pq0.setting_sec_A - 0.9375) < 1e-12, 'Q0 secondary 0.9375 A');
T = T.chk(abs(Pq0.tms - 0.80) < 1e-12 && strcmp(Pq0.assumption_class, 'CONDITIONAL'), 'Q0 TMS 0.80 CONDITIONAL');
% 5. GEN-51N dedicated neutral CT
e = R.devices(strcmp(ids, 'GEN-51N'));
T = T.chk(e.ct_ratio == 20 && strcmp(e.ct_source, 'ENGINEERING_ASSUMPTION'), 'GEN-51N neutral CT 20/1 ENGINEERING_ASSUMPTION');
Pe = phase5b_pickup(e, 0, 7.27013);
T = T.chk(abs(Pe.setting - 4) < 1e-12 && abs(Pe.setting_sec_A - 0.20) < 1e-12, 'GEN-51N PRIMARY 4A/0.20Asec');
T = T.chk(abs(Pe.tms - 0.15) < 1e-12 && strcmp(Pe.assumption_class, 'PRIMARY'), 'GEN-51N TMS 0.15 PRIMARY');
% 6. PRIMARY/SENSITIVITY separation (pickup engine has no 5A branch)
try
    phase5b_pickup(e, 0, 7.27);
    has5A = (Pe.setting == 5);
catch
    has5A = false;
end
T = T.chk(~has5A, '5A GEN-51N absent from PRIMARY pickup engine');
% 7. Runner calls Phase-5b tests
src = fileread(which('run_phase5b_production'));
T = T.chk(~isempty(strfind(src, '[NP, NF] = run_phase5b_tests()')), 'runner calls run_phase5b_tests');
T = T.chk(isempty(strfind(src, '[NP, NF] = run_phase5_tests()')), 'runner free of stale v1 call');
% 8. 87G pending-data status
d87 = R.devices(strcmp(ids, 'GEN-87G'));
T = T.chk(abs(d87.pickup_A - 2403.8) < 0.2, '87G 2403.8 A study threshold');
% 9. 87T study-proxy status
srcEff = fileread(which('phase5b_effectiveness'));
T = T.chk(isempty(strfind(srcEff, 'ASSERTABLE-DETECT')), '87T no ASSERTABLE-DETECT (study proxy only)');
T = T.chk(~isempty(strfind(srcEff, 'STUDY-DETECTABILITY')), 'STUDY-DETECTABILITY vocabulary present');
% 10. Q0 conditional breaker-duty handling
T = T.chk(strcmp(q.assumption_class, 'CONDITIONAL'), 'Q0 assumption_class CONDITIONAL');
% 11. Assumption/provenance consistency (assumptions CSV exists with central rows)
T = T.chk(exist(fullfile(ashuganj_root(), 'PHASE5_ASSUMPTIONS.csv'), 'file') == 2, 'PHASE5_ASSUMPTIONS.csv exists');
aText = fileread(fullfile(ashuganj_root(), 'PHASE5_ASSUMPTIONS.csv'));
T = T.chk(~isempty(strfind(aText, 'GIS_Q0_51_pickup_primary,1500')), 'assumptions carry Q0 1500');
T = T.chk(~isempty(strfind(aText, 'GEN_51N_CT_ratio,20/1')), 'assumptions carry 20/1 neutral CT');
[np, nf] = T.done();
end

